import json
rows={d['Z']:d for d in map(json.loads,open('nlchain.jsonl'))}
NL=lambda k:(int(k[:-1]),'spdfg'.index(k[-1]))
print(' Z  ent  n+l    D_ent    margin   runner-up        converged-set')
viol=[];tb=[];nulls={}
for Z in range(109,121):
    r=rows[Z]; e=tuple(r['ent_nl']); nl=sum(e)
    od=dict(r['order']); srt=r['order']
    ru=srt[1] if len(srt)>1 else ('-',0.0)
    for k,v in od.items():
        n,l=NL(k)
        if n+l<nl and v>r['D_ent']: viol.append((Z,k,v))
        if n+l==nl and n<e[0] and v>r['D_ent']: tb.append((Z,k,v))
    for k in r.get('fail',{}): nulls.setdefault(k,[]).append(Z)
    print(f' {Z} {r[\"ent\"]:>4} {nl:>4} {r[\"D_ent\"]:>9.5f} {r[\"margin\"]:>8.5f}  {ru[0]:>3} {ru[1]:>8.5f}   {\" \".join(k for k,_ in srt)}')
print()
print('ORDERING failures :', viol or 'NONE')
print('TIE-BREAK failures:', tb or 'NONE')
print()
print('NON-CONVERGED CHANNELS (nulls), by channel -> Z list:')
for k in sorted(nulls,key=lambda x:(NL(x)[0]+NL(x)[1],NL(x)[0])):
    n,l=NL(k); print(f'  {k:>3} n+l={n+l}  {len(nulls[k]):>2} of 12  Z={nulls[k]}')
"

