for c in chans:
    vs={rows[Z]['order'] and dict(rows[Z]['order']).get(c) for Z in range(109,121)}
    vs={v for v in vs if v is not None}
    if len(vs)==1: print(f'  {c}: pinned at {vs.pop()}')
"

